local RoofTileMaker = {}
local PRODUCTS = {
    simple_clay_roof_tile = { name = "Preprosta glinena strešnik", clayCost = 2, time = 3, cost = 30, defense = 8, happiness = 1, description = "Preprosta glinena strešnik za hišo." },
    fired_pantile = { name = "Žgana pantile", clayCost = 2, woodCost = 1, time = 5, cost = 80, defense = 14, happiness = 1, prestige = 2, description = "Žgana pantile za trgovce." },
    glazed_blue_tile = { name = "Glazurasta modra strešnik", clayCost = 2, glassCost = 1, woodCost = 1, time = 8, cost = 200, defense = 22, happiness = 2, prestige = 6, description = "Glazurasta modra strešnik za plemiče." },
    silver_ridged_tile = { name = "Srebrnogrebena strešnik", clayCost = 2, silverCost = 1, glassCost = 1, woodCost = 1, time = 12, cost = 480, defense = 32, happiness = 3, prestige = 14, description = "Srebrnogrebena strešnik za visoke plemiče." },
    gold_trimmed_tile = { name = "Zlatookrasna strešnik", clayCost = 2, goldCost = 1, silverCost = 1, glassCost = 1, woodCost = 1, jewelCost = 1, time = 16, cost = 1100, defense = 42, happiness = 5, prestige = 27, description = "Zlatookrasna strešnik z draguljem za visoko plemstvo." },
    royal_grand_roof_tile = { name = "Kraljevski veliki strešnik", clayCost = 3, goldCost = 2, silverCost = 2, glassCost = 2, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 2800, defense = 55, happiness = 12, prestige = 58, description = "Veliki kraljevski strešnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tile_workshop = { name = "Strešniška delavnica", cost = { gold = 220, wood = 120, stone = 120, clay = 6 }, upkeep = 5, qualityBonus = 5 },
    kiln_loft = { name = "Pečna podstrešje", cost = { gold = 880, wood = 260, stone = 280, glass = 6, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    master_tile_atelier = { name = "Mojstrski strešniški atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_roofing_palace = { name = "Kraljevska strešniška palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
RoofTileMaker.clayStock = 18; RoofTileMaker.woodStock = 12; RoofTileMaker.glassStock = 12; RoofTileMaker.silverStock = 6; RoofTileMaker.goldStock = 6; RoofTileMaker.jewelStock = 4; RoofTileMaker.pearlStock = 4
RoofTileMaker.productStock = {}; RoofTileMaker.buildings = {}; RoofTileMaker.maker = nil; RoofTileMaker.activeMaking = {}; RoofTileMaker.totalProducts = 0; RoofTileMaker.dayTimer = 0
function RoofTileMaker.init() RoofTileMaker.clayStock=18; RoofTileMaker.woodStock=12; RoofTileMaker.glassStock=12; RoofTileMaker.silverStock=6; RoofTileMaker.goldStock=6; RoofTileMaker.jewelStock=4; RoofTileMaker.pearlStock=4; RoofTileMaker.productStock={}; RoofTileMaker.buildings={}; RoofTileMaker.maker=nil; RoofTileMaker.activeMaking={}; RoofTileMaker.totalProducts=0; RoofTileMaker.dayTimer=0; print("[RoofTileMaker] Royal Roof Tile Maker System initialized (6 products, 4 buildings)") end
function RoofTileMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RoofTileMaker.maker={name=n or ("Strešničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strešničar najet: %s (spretnost: %d)",RoofTileMaker.maker.name,s),"success") end; return true end
function RoofTileMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RoofTileMaker.build(id) local ok,e=RoofTileMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RoofTileMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RoofTileMaker.getQualityBonus() local b=0; for _,bd in ipairs(RoofTileMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RoofTileMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and RoofTileMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.woodCost and RoofTileMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.glassCost and RoofTileMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and RoofTileMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RoofTileMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RoofTileMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RoofTileMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RoofTileMaker.buildings==0 then return false,"Potrebna strešniška delavnica" end; if not RoofTileMaker.maker then return false,"Potreben strešničar" end; return true end
function RoofTileMaker.make(pt,qty) qty=qty or 1; local ok,e=RoofTileMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then RoofTileMaker.clayStock=RoofTileMaker.clayStock-d.clayCost*qty end; if d.woodCost then RoofTileMaker.woodStock=RoofTileMaker.woodStock-d.woodCost*qty end; if d.glassCost then RoofTileMaker.glassStock=RoofTileMaker.glassStock-d.glassCost*qty end; if d.silverCost then RoofTileMaker.silverStock=RoofTileMaker.silverStock-d.silverCost*qty end; if d.goldCost then RoofTileMaker.goldStock=RoofTileMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RoofTileMaker.jewelStock=RoofTileMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then RoofTileMaker.pearlStock=RoofTileMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if RoofTileMaker.maker then t=math.max(1,t-math.floor(RoofTileMaker.maker.skill/13)) end; table.insert(RoofTileMaker.activeMaking,{id="rooftile_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RoofTileMaker.completeMaking(m) local q=1.0+(RoofTileMaker.getQualityBonus()/100); if RoofTileMaker.maker then q=q+(RoofTileMaker.maker.skill/140) end; q=math.min(2.5,q); RoofTileMaker.productStock[m.productType]=(RoofTileMaker.productStock[m.productType] or 0)+m.quantity; RoofTileMaker.totalProducts=RoofTileMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RoofTileMaker.maker then RoofTileMaker.maker.itemsMade=RoofTileMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then RoofTileMaker.maker.skill=math.min(100,RoofTileMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strešnik izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"rooftile.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function RoofTileMaker.update(dt) if not _G.state then return end; RoofTileMaker.dayTimer=RoofTileMaker.dayTimer+dt; if RoofTileMaker.dayTimer>=30 then RoofTileMaker.dayTimer=0; for i=#RoofTileMaker.activeMaking,1,-1 do local m=RoofTileMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RoofTileMaker.completeMaking(m); table.remove(RoofTileMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RoofTileMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RoofTileMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RoofTileMaker.getStats() return {clayStock=RoofTileMaker.clayStock,woodStock=RoofTileMaker.woodStock,glassStock=RoofTileMaker.glassStock,silverStock=RoofTileMaker.silverStock,goldStock=RoofTileMaker.goldStock,jewelStock=RoofTileMaker.jewelStock,pearlStock=RoofTileMaker.pearlStock,productStock=RoofTileMaker.productStock,numBuildings=#RoofTileMaker.buildings,hasMaker=RoofTileMaker.maker~=nil,makerName=RoofTileMaker.maker and RoofTileMaker.maker.name or "—",makerSkill=RoofTileMaker.maker and RoofTileMaker.maker.skill or 0,activeMaking=#RoofTileMaker.activeMaking,totalProducts=RoofTileMaker.totalProducts} end
return RoofTileMaker
